36: // Wrapper around net::URLRequestContext.
37: // Created and configured from client thread. Start, ReadData, and Destroy are
38: // posted to network thread and all callbacks into the Callback() are
39: // done on the network thread. CronetUrlRequest client is expected to initiate
40: // the next step like FollowDeferredRedirect, ReadData or Destroy. Public
41: // methods can be called on any thread.
42: class CronetURLRequest {
43:  public:
44:   // Callback implemented by CronetURLRequest() caller and owned by
45:   // CronetURLRequest::NetworkTasks. All callback methods are invoked on network
46:   // thread.
47:   class Callback {
48:    public:
49:     virtual ~Callback() = default;
50: 
51:     // Invoked whenever a redirect is encountered. This will only be invoked
52:     // between the call to CronetURLRequest::Start() and
53:     // Callback::OnResponseStarted(). The body of the redirect response, if
54:     // it has one, will be ignored.
55:     //
56:     // The redirect will not be followed until
57:     // CronetURLRequest::FollowDeferredRedirect() method is called, either
58:     // synchronously or asynchronously.
59:     virtual void OnReceivedRedirect(const std::string& new_location,
60:                                     int http_status_code,
61:                                     const std::string& http_status_text,
62:                                     const net::HttpResponseHeaders* headers,
63:                                     bool was_cached,
64:                                     const std::string& negotiated_protocol,
65:                                     const std::string& proxy_server,
66:                                     int64_t received_byte_count) = 0;
67: 
68:     // Invoked when the final set of headers, after all redirects, is received.
69:     // Will only be invoked once for each request.
70:     //
71:     // With the exception of Callback::OnCanceled(),
72:     // no other Callback method will be invoked for the request,
73:     // including Callback::OnSucceeded() and Callback::OnFailed(), until
74:     // CronetUrlRequest::Read() is called to attempt to start reading the
75:     // response body.
76:     virtual void OnResponseStarted(int http_status_code,
77:                                    const std::string& http_status_text,
78:                                    const net::HttpResponseHeaders* headers,
79:                                    bool was_cached,
80:                                    const std::string& negotiated_protocol,
81:                                    const std::string& proxy_server,
82:                                    int64_t received_byte_count,
83:                                    bool is_proxied) = 0;
84: 
85:     // Invoked whenever part of the response body has been read. Only part of
86:     // the buffer may be populated, even if the entire response body has not yet
87:     // been consumed.
88:     //
89:     // With the exception of Callback::OnCanceled(),
90:     // no other Callback method will be invoked for the request,
91:     // including Callback::OnSucceeded() and Callback::OnFailed(), until
92:     // CronetUrlRequest::Read() is called to attempt to continue reading the
93:     // response body.
94:     virtual void OnReadCompleted(scoped_refptr<net::IOBuffer> buffer,
95:                                  int bytes_read,
96:                                  int64_t received_byte_count) = 0;
97: 
98:     // Invoked when request is completed successfully.
99:     virtual void OnSucceeded(int64_t received_byte_count) = 0;
100: 
101:     // Invoked if request failed for any reason after CronetURLRequest::Start().
102:     // |net_error| provides information about the failure. |quic_error| is only
103:     // valid if |net_error| is net::QUIC_PROTOCOL_ERROR.
104:     // |source| represents who asked to terminate the connection, it is only
105:     // valid if the |net_error| is net::QUIC_PROTOCOL_ERROR.
106:     virtual void OnError(int net_error,
107:                          int quic_error,
108:                          quic::ConnectionCloseSource source,
109:                          const std::string& error_string,
110:                          int64_t received_byte_count) = 0;
111: 
112:     // Invoked if request was canceled via CronetURLRequest::Destroy().
113:     virtual void OnCanceled() = 0;
114: 
115:     // Invoked when request is destroyed. Once invoked, no other Callback
116:     // methods will be invoked.
117:     virtual void OnDestroyed() = 0;
118: 
119:     // Reports metrics data about the request.
120:     // This is called immediately before the terminal state callback (i.e.
121:     // OnSucceeded()/OnError()/OnCanceled()).
122:     virtual void OnMetricsCollected(
123:         const base::Time& request_start_time,
124:         const base::TimeTicks& request_start,
125:         const base::TimeTicks& dns_start,
126:         const base::TimeTicks& dns_end,
127:         const base::TimeTicks& connect_start,
128:         const base::TimeTicks& connect_end,
129:         const base::TimeTicks& ssl_start,
130:         const base::TimeTicks& ssl_end,
131:         const base::TimeTicks& send_start,
132:         const base::TimeTicks& send_end,
133:         const base::TimeTicks& push_start,
134:         const base::TimeTicks& push_end,
135:         const base::TimeTicks& receive_headers_end,
136:         const base::TimeTicks& request_end,
137:         bool socket_reused,
138:         int64_t sent_bytes_count,
139:         int64_t received_bytes_count,
140:         bool quic_connection_migration_attempted,
141:         bool quic_connection_migration_successful) = 0;
142:   };
143:   // Invoked in response to CronetURLRequest::GetStatus() to allow multiple
144:   // overlapping calls. The load states correspond to the lengthy periods of
145:   // time that a request load may be blocked and unable to make progress.
146:   using OnStatusCallback = base::OnceCallback<void(net::LoadState)>;
