82: // Converts a network-quality observation TimeTicks into milliseconds since the
83: // Unix epoch (the value exposed through the Cronet API) by anchoring both
84: // clocks to the current instant.
85: int64_t TimeTicksToMillisecondsSinceUnixEpoch(const base::TimeTicks& ticks) {
86:   return (base::Time::Now() - (base::TimeTicks::Now() - ticks) -
87:           base::Time::UnixEpoch())
88:       .InMilliseconds();
89: }
