91: // This class wraps a NetLog that also contains network change events.
92: class NetLogWithNetworkChangeEvents {
93:  public:
94:   NetLogWithNetworkChangeEvents() : net_log_(net::NetLog::Get()) {}
95: 
96:   NetLogWithNetworkChangeEvents(const NetLogWithNetworkChangeEvents&) = delete;
97:   NetLogWithNetworkChangeEvents& operator=(
98:       const NetLogWithNetworkChangeEvents&) = delete;
99: 
100:   net::NetLog* net_log() { return net_log_; }
101:   // This function registers with the NetworkChangeNotifier and so must be
102:   // called *after* the NetworkChangeNotifier is created. Should only be
103:   // called on the init thread as it is not thread-safe and the init thread is
104:   // the thread the NetworkChangeNotifier is created on. This function is
105:   // not thread-safe because accesses to `net_change_logger_` are not atomic.
106:   // There might be multiple CronetEngines each with a network thread so
107:   // so the init thread is used. `net_log_` also outlives the network threads
108:   // so it would be unsafe to receive callbacks on the network threads without
109:   // a complicated thread-safe reference-counting system to control callback
110:   // registration.
111:   void EnsureInitializedOnInitThread() {
112:     DCHECK(cronet::OnInitThread());
113:     if (net_change_logger_)
114:       return;
115:     net_change_logger_ =
116:         std::make_unique<net::LoggingNetworkChangeObserver>(net_log_);
117:   }
118: 
119:  private:
120:   raw_ptr<net::NetLog> net_log_;
121:   // LoggingNetworkChangeObserver logs network change events to a NetLog.
122:   // This class bundles one LoggingNetworkChangeObserver with one NetLog,
123:   // so network change event are logged just once in the NetLog.
124:   std::unique_ptr<net::LoggingNetworkChangeObserver> net_change_logger_;
125: };
126: 
127: // Use a global NetLog instance. See crbug.com/486120.
128: NetLogWithNetworkChangeEvents& GetNetLog() {
129:   static base::NoDestructor<NetLogWithNetworkChangeEvents> net_log;
130:   return *net_log;
131: }
