167: // Helper function to make a net::URLRequestContext aware of a QUIC hint.
168: void SetQuicHint(net::URLRequestContext* context,
169:                  const cronet::URLRequestContextConfig::QuicHint* quic_hint) {
170:   if (quic_hint->host.empty()) {
171:     LOG(ERROR) << "Empty QUIC hint host: " << quic_hint->host;
172:     return;
173:   }
174: 
175:   url::CanonHostInfo host_info;
176:   std::string canon_host(net::CanonicalizeHost(quic_hint->host, &host_info));
177:   if (!host_info.IsIPAddress() &&
178:       !net::IsCanonicalizedHostCompliant(canon_host)) {
179:     LOG(ERROR) << "Invalid QUIC hint host: " << quic_hint->host;
180:     return;
181:   }
182: 
183:   if (quic_hint->port <= std::numeric_limits<uint16_t>::min() ||
184:       quic_hint->port > std::numeric_limits<uint16_t>::max()) {
185:     LOG(ERROR) << "Invalid QUIC hint port: " << quic_hint->port;
186:     return;
187:   }
188: 
189:   if (quic_hint->alternate_port <= std::numeric_limits<uint16_t>::min() ||
190:       quic_hint->alternate_port > std::numeric_limits<uint16_t>::max()) {
191:     LOG(ERROR) << "Invalid QUIC hint alternate port: "
192:                << quic_hint->alternate_port;
193:     return;
194:   }
195: 
196:   url::SchemeHostPort quic_server("https", canon_host, quic_hint->port);
197:   net::AlternativeService alternative_service(
198:       net::NextProto::kProtoQUIC, "",
199:       static_cast<uint16_t>(quic_hint->alternate_port));
200:   context->http_server_properties()->SetQuicAlternativeService(
201:       quic_server, net::NetworkAnonymizationKey(), alternative_service,
202:       base::Time::Max(), quic::ParsedQuicVersionVector());
203: }
