205: // net::NetworkChangeNotifier doesn't provide an API to query if a specific
206: // network has become disconnected. For these network though, it will return
207: // CONNECTION_UNKNOWN as their connection type. This should be a good enough
208: // approximation for the time being.
209: bool IsNetworkNoLongerConnected(net::handles::NetworkHandle network) {
210:   return net::NetworkChangeNotifier::GetNetworkConnectionType(network) ==
211:          net::NetworkChangeNotifier::CONNECTION_UNKNOWN;
212: }
