371: std::unique_ptr<net::URLRequestContext>
372: CronetContext::NetworkTasks::BuildDefaultURLRequestContext(
373:     std::unique_ptr<net::ProxyConfigService> proxy_config_service) {
374:   DCHECK(!network_quality_estimator_);
375:   DCHECK(!cronet_prefs_manager_);
376:   net::URLRequestContextBuilder context_builder;
377:   context_config_->ConfigureURLRequestContextBuilder(&context_builder, this);
378:   SetSharedURLRequestContextBuilderConfig(&context_builder);
379: 
380:   context_builder.set_proxy_resolution_service(
381:       cronet::CreateProxyResolutionService(std::move(proxy_config_service),
382:                                            GetNetLog().net_log()));
383: 
384:   if (context_config_->enable_network_quality_estimator) {
385:     std::unique_ptr<net::NetworkQualityEstimatorParams> nqe_params =
386:         std::make_unique<net::NetworkQualityEstimatorParams>(
387:             std::map<std::string, std::string>());
388:     if (context_config_->nqe_forced_effective_connection_type) {
389:       nqe_params->SetForcedEffectiveConnectionType(
390:           context_config_->nqe_forced_effective_connection_type.value());
391:     }
392: 
393:     network_quality_estimator_ = std::make_unique<net::NetworkQualityEstimator>(
394:         std::move(nqe_params), GetNetLog().net_log());
395:     network_quality_estimator_->AddEffectiveConnectionTypeObserver(this);
396:     network_quality_estimator_->AddRTTAndThroughputEstimatesObserver(this);
397: 
398:     context_builder.set_network_quality_estimator(
399:         network_quality_estimator_.get());
400:   }
401: 
402:   // Set up pref file if storage path is specified.
403:   if (!context_config_->storage_path.empty()) {
404: #if BUILDFLAG(IS_WIN)
405:     base::FilePath storage_path(
406:         base::FilePath::FromUTF8Unsafe(context_config_->storage_path));
407: #else
408:     base::FilePath storage_path(context_config_->storage_path);
409: #endif
410:     // Currently only the default context uses a PrefManager, this means that
411:     // contexts for specific networks do not maintain state between restarts.
412:     // Part of that is by design, part of that is due to CronetPrefsManager's
413:     // current interface: it assumes that a single URLRequestContext exists
414:     // and, under that assumption, mixes NQE, HostCache, and
415:     // HttpServerProperties management persistence. The former two should
416:     // apply only to the default context, while the latter could also be
417:     // applied to network-bound contexts.
418:     // TODO(stefanoduo): Decouple CronetPrefManager management of NQE,
419:     // HostCache and HttpServerProperties and apply HttpServerProperties to
420:     // network bound contexts.
421:     cronet_prefs_manager_ = std::make_unique<CronetPrefsManager>(
422:         context_config_->storage_path, network_task_runner_, file_task_runner_,
423:         context_config_->enable_network_quality_estimator,
424:         context_config_->enable_host_cache_persistence, GetNetLog().net_log(),
425:         &context_builder);
426:   }
427: 
428:   auto context = context_builder.Build();
429: 
430:   // Set up host cache persistence if it's enabled. Happens after building the
431:   // URLRequestContext to get access to the HostCache.
432:   if (context_config_->enable_host_cache_persistence && cronet_prefs_manager_) {
433:     net::HostCache* host_cache = context->host_resolver()->GetHostCache();
434:     cronet_prefs_manager_->SetupHostCachePersistence(
435:         host_cache, context_config_->host_cache_persistence_delay_ms,
436:         GetNetLog().net_log());
437:   }
438: 
439:   SetSharedURLRequestContextConfig(context.get());
440:   return context;
441: }
