443: std::unique_ptr<net::URLRequestContext>
444: CronetContext::NetworkTasks::BuildNetworkBoundURLRequestContext(
445:     net::handles::NetworkHandle network) {
446:   net::URLRequestContextBuilder context_builder;
447:   context_config_->ConfigureURLRequestContextBuilder(&context_builder, this,
448:                                                      network);
449:   SetSharedURLRequestContextBuilderConfig(&context_builder);
450: 
451:   // On Android, Cronet doesn't handle PAC URL processing, instead it defers
452:   // that to the OS (which sets up a local proxy configured correctly w.r.t.
453:   // Android settings). See crbug.com/432539.
454:   // TODO(stefanoduo): Confirm if we can keep using this configuration for
455:   // requests bound to a network (otherwise we might have to query that
456:   // network's LinkProperties#getHttpProxy).
457:   // Until then don't support proxies when a network is specified.
458:   context_builder.set_proxy_config_service(
459:       std::make_unique<net::ProxyConfigServiceFixed>(
460:           net::ProxyConfigWithAnnotation::CreateDirect()));
461: 
462:   auto context = context_builder.Build();
463:   SetSharedURLRequestContextConfig(context.get());
464:   return context;
465: }
