467: void CronetContext::NetworkTasks::SetSharedURLRequestContextBuilderConfig(
468:     net::URLRequestContextBuilder* context_builder) {
469:   context_builder->set_network_delegate(
470:       std::make_unique<BasicNetworkDelegate>());
471:   context_builder->set_net_log(GetNetLog().net_log());
472: 
473:   // Explicitly disable the persister for Cronet to avoid persistence of dynamic
474:   // HPKP. This is a safety measure ensuring that nobody enables the persistence
475:   // of HPKP by specifying transport_security_persister_file_path in the future.
476:   context_builder->set_transport_security_persister_file_path(base::FilePath());
477: 
478:   // Disable net::CookieStore.
479:   context_builder->SetCookieStore(nullptr);
480: 
481:   context_builder->set_check_cleartext_permitted(true);
482:   context_builder->set_enable_brotli(context_config_->enable_brotli);
483:   context_builder->set_enable_zstd(base::FeatureList::IsEnabled(kEnableZstd));
484:   context_builder->set_enable_shared_dictionary(context_config_->enable_brotli);
485: }
