487: void CronetContext::NetworkTasks::SetSharedURLRequestContextConfig(
488:     net::URLRequestContext* context) {
489:   if (context_config_->enable_quic) {
490:     for (const auto& quic_hint : context_config_->quic_hints)
491:       SetQuicHint(context, quic_hint.get());
492:   }
493: 
494:   // Iterate through PKP configuration for every host.
495:   for (const auto& pkp : context_config_->pkp_list) {
496:     // Add the host pinning.
497:     context->transport_security_state()->AddHPKP(
498:         pkp->host, pkp->expiration_date, pkp->include_subdomains,
499:         pkp->pin_hashes);
500:   }
501: 
502:   context->transport_security_state()
503:       ->SetEnablePublicKeyPinningBypassForLocalTrustAnchors(
504:           context_config_->bypass_public_key_pinning_for_local_trust_anchors);
505: 
506: #if BUILDFLAG(ENABLE_REPORTING)
507:   if (context->reporting_service()) {
508:     for (const auto& preloaded_header :
509:          context_config_->preloaded_report_to_headers) {
510:       context->reporting_service()->ProcessReportToHeader(
511:           preloaded_header.origin, net::NetworkAnonymizationKey(),
512:           preloaded_header.value);
513:     }
514:   }
515: 
516:   if (context->network_error_logging_service()) {
517:     for (const auto& preloaded_header :
518:          context_config_->preloaded_nel_headers) {
519:       context->network_error_logging_service()->OnHeader(
520:           net::NetworkAnonymizationKey(), preloaded_header.origin,
521:           net::IPAddress(), preloaded_header.value);
522:     }
523:   }
524: #endif  // BUILDFLAG(ENABLE_REPORTING)
525: }
