527: void CronetContext::NetworkTasks::Initialize(
528:     scoped_refptr<base::SingleThreadTaskRunner> network_task_runner,
529:     scoped_refptr<base::SequencedTaskRunner> file_task_runner,
530:     std::unique_ptr<net::ProxyConfigService> proxy_config_service) {
531:   DCHECK_CALLED_ON_VALID_THREAD(network_thread_checker_);
532:   DCHECK(!is_default_context_initialized_);
533: 
534:   network_task_runner_ = network_task_runner;
535:   file_task_runner_ = file_task_runner;
536:   if (context_config_->network_thread_priority)
537:     SetNetworkThreadPriorityOnNetworkThread(
538:         context_config_->network_thread_priority.value());
539:   base::DisallowBlocking();
540:   effective_experimental_options_ =
541:       context_config_->effective_experimental_options.Clone();
542: 
543:   const net::handles::NetworkHandle default_network =
544:       net::handles::kInvalidNetworkHandle;
545:   contexts_[default_network] =
546:       BuildDefaultURLRequestContext(std::move(proxy_config_service));
547:   default_context_ = contexts_[default_network].get();
548: 
549:   if (net::NetworkChangeNotifier::AreNetworkHandlesSupported())
550:     net::NetworkChangeNotifier::AddNetworkObserver(this);
551: 
552:   callback_->OnInitNetworkThread();
553:   is_default_context_initialized_ = true;
554: 
555:   if (context_config_->enable_network_quality_estimator &&
556:       cronet_prefs_manager_) {
557:     cronet_prefs_manager_->SetupNqePersistence(
558:         network_quality_estimator_.get());
559:   }
560: 
561:   while (!tasks_waiting_for_context_.empty()) {
562:     std::move(tasks_waiting_for_context_.front()).Run();
563:     tasks_waiting_for_context_.pop();
564:   }
565: }
