567: net::URLRequestContext* CronetContext::NetworkTasks::GetURLRequestContext(
568:     net::handles::NetworkHandle network) {
569:   DCHECK_CALLED_ON_VALID_THREAD(network_thread_checker_);
570:   DCHECK(is_default_context_initialized_);
571: 
572:   if (network == net::handles::kInvalidNetworkHandle)
573:     return default_context_;
574: 
575:   // Non-default contexts are created on the fly.
576:   if (contexts_.find(network) == contexts_.end())
577:     contexts_[network] = BuildNetworkBoundURLRequestContext(network);
578:   return contexts_[network].get();
