581: void CronetContext::NetworkTasks::MaybeDestroyURLRequestContext(
582:     net::handles::NetworkHandle network) {
583:   DCHECK_CALLED_ON_VALID_THREAD(network_thread_checker_);
584: 
585:   // Default network context is never deleted.
586:   if (network == net::handles::kInvalidNetworkHandle)
587:     return;
588:   auto it = contexts_.find(network);
589:   if (it == contexts_.end()) {
590:     return;
591:   }
592: 
593:   auto& context = it->second;
594:   // For a URLRequestContext to be destroyed, two conditions must be satisfied:
595:   // 1. The network associated to that context must be no longer connected
596:   // 2. There must be no URLRequests associated to that context
597:   if (context->url_requests()->size() == 0 &&
598:       IsNetworkNoLongerConnected(network)) {
599:     contexts_.erase(it);
600:   }
