46: int CalculateLoadFlags(int load_flags,
47:                        bool disable_cache,
48:                        bool disable_connection_migration) {
49:   if (disable_cache)
50:     load_flags |= net::LOAD_DISABLE_CACHE;
51:   if (disable_connection_migration)
52:     load_flags |= net::LOAD_DISABLE_CONNECTION_MIGRATION_TO_CELLULAR;
53:   return load_flags;
54: }
