95: bool CronetURLRequest::SetHttpMethod(const std::string& method) {
96:   DCHECK(!context_->IsOnNetworkThread());
97:   // Http method is a token, just as header name.
98:   if (!net::HttpUtil::IsValidHeaderName(method))
99:     return false;
100:   initial_method_ = method;
101:   return true;
102: }
