104: bool CronetURLRequest::AddRequestHeader(const std::string& name,
105:                                         const std::string& value) {
106:   DCHECK(!context_->IsOnNetworkThread());
107:   DCHECK(initial_request_headers_);
108:   if (!net::HttpUtil::IsValidHeaderName(name) ||
109:       !net::HttpUtil::IsValidHeaderValue(value)) {
110:     return false;
111:   }
112:   initial_request_headers_->SetHeader(name, value);
113:   return true;
114: }
