160: void CronetURLRequest::Destroy(bool send_on_canceled) {
161:   // Destroy could be called from any thread, including network thread (if
162:   // posting task to executor throws an exception), but is posted, so |this|
163:   // is valid until calling task is complete. Destroy() must be called from
164:   // within a synchronized block that guarantees no future posts to the
165:   // network thread with the request pointer.
166:   context_->PostTaskToNetworkThread(
167:       FROM_HERE, base::BindOnce(&CronetURLRequest::NetworkTasks::Destroy,
168:                                 base::Unretained(&network_tasks_),
169:                                 base::Unretained(this), send_on_canceled));
170: }
