214: void CronetURLRequest::NetworkTasks::OnReceivedRedirect(
215:     net::URLRequest* request,
216:     const net::RedirectInfo& redirect_info,
217:     bool* defer_redirect) {
218:   DCHECK_CALLED_ON_VALID_THREAD(network_thread_checker_);
219:   received_byte_count_from_redirects_ +=
220:       request->GetTotalReceivedBytes().InBytes();
221:   callback_->OnReceivedRedirect(
222:       redirect_info.new_url.spec(), redirect_info.status_code,
223:       request->response_headers()->GetStatusText(), request->response_headers(),
224:       request->response_info().was_cached,
225:       request->response_info().alpn_negotiated_protocol,
226:       metrics_util::GetProxy(request->response_info().proxy_chain),
227:       received_byte_count_from_redirects_);
228:   *defer_redirect = true;
229: }
