249: void CronetURLRequest::NetworkTasks::OnResponseStarted(net::URLRequest* request,
250:                                                        int net_error) {
251:   DCHECK_NE(net::ERR_IO_PENDING, net_error);
252:   DCHECK_CALLED_ON_VALID_THREAD(network_thread_checker_);
253: 
254:   if (net_error != net::OK) {
255:     ReportError(request, net_error);
256:     return;
257:   }
258:   callback_->OnResponseStarted(
259:       request->GetResponseCode(), request->response_headers()->GetStatusText(),
260:       request->response_headers(), request->response_info().was_cached,
261:       request->response_info().alpn_negotiated_protocol,
262:       metrics_util::GetProxy(request->response_info().proxy_chain),
263:       received_byte_count_from_redirects_ +
264:           request->GetTotalReceivedBytes().InBytes(),
265:       metrics_util::IsProxied(request->response_info().proxy_chain));
266: }
