268: void CronetURLRequest::NetworkTasks::OnReadCompleted(net::URLRequest* request,
269:                                                      int bytes_read) {
270:   DCHECK_CALLED_ON_VALID_THREAD(network_thread_checker_);
271: 
272:   if (bytes_read < 0) {
273:     ReportError(request, bytes_read);
274:     return;
275:   }
276: 
277:   if (bytes_read == 0) {
278:     DCHECK(!error_reported_);
279:     MaybeReportMetrics();
280:     callback_->OnSucceeded(received_byte_count_from_redirects_ +
281:                            request->GetTotalReceivedBytes().InBytes());
282:   } else {
283:     callback_->OnReadCompleted(read_buffer_, bytes_read,
284:                                received_byte_count_from_redirects_ +
285:                                    request->GetTotalReceivedBytes().InBytes());
286:   }
287:   // Free the read buffer.
288:   read_buffer_ = nullptr;
289: }
