291: void CronetURLRequest::NetworkTasks::Start(
292:     CronetContext* context,
293:     const std::string& method,
294:     std::unique_ptr<net::HttpRequestHeaders> request_headers,
295:     std::unique_ptr<net::UploadDataStream> upload) {
296:   DCHECK(context->IsOnNetworkThread());
297:   DCHECK_CALLED_ON_VALID_THREAD(network_thread_checker_);
298:   VLOG(1) << "Starting chromium request: "
299:           << initial_url_.possibly_invalid_spec().c_str()
300:           << " priority: " << RequestPriorityToString(initial_priority_);
301:   url_request_ = context->GetURLRequestContext(network_)->CreateRequest(
302:       initial_url_, net::DEFAULT_PRIORITY, this, MISSING_TRAFFIC_ANNOTATION);
303:   url_request_->SetLoadFlags(initial_load_flags_);
304:   url_request_->set_method(method);
305:   url_request_->SetExtraRequestHeaders(*request_headers);
306:   url_request_->SetPriority(initial_priority_);
307:   url_request_->SetIdempotency(idempotency_);
308:   url_request_->SetReferrer(
309:       request_headers->GetHeader(net::HttpRequestHeaders::kReferer)
310:           .value_or(url_request_->referrer()));
311:   url_request_->set_referrer_policy(net::ReferrerPolicy::NEVER_CLEAR);
312:   if (shared_dictionary_) {
313:     if (!context->GetURLRequestContext(network_)->enable_brotli()) {
314:       // Ideally this would be impossible. Unfortunately, due to Cronet's API
315:       // structure, it is impossible to know within UrlRequest.Builder's API
316:       // code whether the associated CronetEngine has Brotli enabled or not.
317:       // So, since we cannot throw there, the best we can do is log error here.
318:       LOG(WARNING) << "Compression dictionary will be ignored: the "
319:                       "CronetEngine being used disables Brotli, which is a "
320:                       "requirement for compression dictionaries.";
321:     } else {
322:       url_request_->SetSharedDictionaryGetter(base::BindRepeating(
323:           [](scoped_refptr<net::SharedDictionary> dict,
324:              const std::optional<net::SharedDictionaryIsolationKey>&
325:                  isolation_key,
326:              const GURL& request_url) {
327:             // Cronet currently does not implement the retrieval of compression
328:             // dictionaries, it instead relies on the embedder to provide them
329:             // for a specific URLRequest. As such, Cronet doesn't handle
330:             // matching dictionaries with isolation keys & URLs, but relies on
331:             // the embedder to do the right thing.
332:             return dict;
333:           },
334:           shared_dictionary_));
335:       url_request_->SetIsSharedDictionaryReadAllowedCallback(
336:           base::BindRepeating([] { return true; }));
337:     }
338:   }
339:   if (upload)
340:     url_request_->set_upload(std::move(upload));
341:   if (traffic_stats_tag_set_ || traffic_stats_uid_set_) {
342: #if BUILDFLAG(IS_ANDROID)
343:     url_request_->set_socket_tag(net::SocketTag(
344:         traffic_stats_uid_set_ ? traffic_stats_uid_ : net::SocketTag::UNSET_UID,
345:         traffic_stats_tag_set_ ? traffic_stats_tag_
346:                                : net::SocketTag::UNSET_TAG));
347: #else
348:     NOTREACHED();
349: #endif
350:   }
351:   url_request_->Start();
352: }
