354: void CronetURLRequest::NetworkTasks::GetStatus(
355:     OnStatusCallback callback) const {
356:   DCHECK_CALLED_ON_VALID_THREAD(network_thread_checker_);
357:   net::LoadState status = net::LOAD_STATE_IDLE;
358:   // |url_request_| is initialized in StartOnNetworkThread, and it is
359:   // never nulled. If it is null, it must be that StartOnNetworkThread
360:   // has not been called, pretend that we are in LOAD_STATE_IDLE.
361:   // See https://crbug.com/606872.
362:   if (url_request_)
363:     status = url_request_->GetLoadState().state;
364:   std::move(callback).Run(status);
365: }
