374: void CronetURLRequest::NetworkTasks::ReadData(
375:     scoped_refptr<net::IOBuffer> read_buffer,
376:     int buffer_size) {
377:   DCHECK_CALLED_ON_VALID_THREAD(network_thread_checker_);
378:   DCHECK(read_buffer);
379:   DCHECK(!read_buffer_);
380: 
381:   read_buffer_ = read_buffer;
382: 
383:   int result = url_request_->Read(read_buffer_.get(), buffer_size);
384:   // If IO is pending, wait for the URLRequest to call OnReadCompleted.
385:   if (result == net::ERR_IO_PENDING)
386:     return;
387: 
388:   OnReadCompleted(url_request_.get(), result);
389: }
