391: void CronetURLRequest::NetworkTasks::Destroy(CronetURLRequest* request,
392:                                              bool send_on_canceled) {
393:   DCHECK_CALLED_ON_VALID_THREAD(network_thread_checker_);
394:   MaybeReportMetrics();
395:   if (send_on_canceled)
396:     callback_->OnCanceled();
397:   callback_->OnDestroyed();
398:   // Check if the URLRequestContext associated to `network_` has become eligible
399:   // for destruction. To simplify MaybeDestroyURLRequestContext's logic: destroy
400:   // the underlying URLRequest in advance, so that it has already deregistered
401:   // from its URLRequestContext by the time MaybeDestroyURLRequestContext is
402:   // called.
403:   url_request_.reset();
404:   request->context_->MaybeDestroyURLRequestContext(network_);
405:   // Deleting owner request also deletes `this`.
406:   delete request;
407: }
