409: void CronetURLRequest::NetworkTasks::ReportError(net::URLRequest* request,
410:                                                  int net_error) {
411:   DCHECK_CALLED_ON_VALID_THREAD(network_thread_checker_);
412:   DCHECK_NE(net::ERR_IO_PENDING, net_error);
413:   DCHECK_LT(net_error, 0);
414:   DCHECK_EQ(request, url_request_.get());
415:   // Error may have already been reported.
416:   if (error_reported_)
417:     return;
418:   error_reported_ = true;
419:   net::NetErrorDetails net_error_details;
420:   url_request_->PopulateNetErrorDetails(&net_error_details);
421:   VLOG(1) << "Error " << net::ErrorToString(net_error)
422:           << " on chromium request: " << initial_url_.possibly_invalid_spec();
423:   MaybeReportMetrics();
424:   callback_->OnError(net_error, net_error_details.quic_connection_error,
425:                      net_error_details.source, net::ErrorToString(net_error),
426:                      received_byte_count_from_redirects_ +
427:                          request->GetTotalReceivedBytes().InBytes());
428: }
