430: void CronetURLRequest::NetworkTasks::MaybeReportMetrics() {
431:   DCHECK_CALLED_ON_VALID_THREAD(network_thread_checker_);
432:   // If there was an exception while starting the CronetUrlRequest, there won't
433:   // be a native URLRequest. In this case, the caller gets the exception
434:   // immediately, and the onFailed callback isn't called, so don't report
435:   // metrics either.
436:   if (metrics_reported_ || !url_request_) {
437:     return;
438:   }
439:   metrics_reported_ = true;
440:   net::LoadTimingInfo metrics;
441:   url_request_->GetLoadTimingInfo(&metrics);
442:   net::NetErrorDetails net_error_details;
443:   url_request_->PopulateNetErrorDetails(&net_error_details);
444:   callback_->OnMetricsCollected(
445:       metrics.request_start_time, metrics.request_start,
446:       metrics.connect_timing.domain_lookup_start,
447:       metrics.connect_timing.domain_lookup_end,
448:       metrics.connect_timing.connect_start, metrics.connect_timing.connect_end,
449:       metrics.connect_timing.ssl_start, metrics.connect_timing.ssl_end,
450:       metrics.send_start, metrics.send_end, metrics.push_start,
451:       metrics.push_end, metrics.receive_headers_end, base::TimeTicks::Now(),
452:       metrics.socket_reused, url_request_->GetTotalSentBytes().InBytes(),
453:       received_byte_count_from_redirects_ +
454:           url_request_->GetTotalReceivedBytes().InBytes(),
455:       net_error_details.quic_connection_migration_attempted,
456:       net_error_details.quic_connection_migration_successful);
457: }
458: 
459: void CronetURLRequest::NetworkTasks::MaybeReportMetricsAndRunCallback(
460:     base::OnceClosure callback) {
461:   DCHECK_CALLED_ON_VALID_THREAD(network_thread_checker_);
462:   MaybeReportMetrics();
463:   std::move(callback).Run();
464: }
