21: // The CronetUploadDataStream is created on a client thread, but afterwards,
22: // lives and is deleted on the network thread. It's responsible for ensuring
23: // only one read/rewind request sent to client is outstanding at a time.
24: // The main complexity is around Reset/Initialize calls while there's a pending
25: // read or rewind.
26: class CronetUploadDataStream : public net::UploadDataStream {
27:  public:
28:   class Delegate {
29:    public:
30:     Delegate(const Delegate&) = delete;
31:     Delegate& operator=(const Delegate&) = delete;
32: 
33:     // Called once during initial setup on the network thread, called before
34:     // all other methods.
35:     virtual void InitializeOnNetworkThread(
36:         base::WeakPtr<CronetUploadDataStream> upload_data_stream) = 0;
37: 
38:     // Called for each read request. Delegate must respond by calling
39:     // OnReadSuccess on the network thread asynchronous, or failing the request.
40:     // Only called when there's no other pending read or rewind operation.
41:     virtual void Read(scoped_refptr<net::IOBuffer> buffer, int buf_len) = 0;
42: 
43:     // Called to rewind the stream. Not called when already at the start of the
44:     // stream. The delegate must respond by calling OnRewindSuccess
45:     // asynchronously on the network thread, or failing the request. Only called
46:     // when there's no other pending read or rewind operation.
47:     virtual void Rewind() = 0;
48: 
49:     // Called when the CronetUploadDataStream is destroyed. The Delegate is then
50:     // responsible for destroying itself. May be called when there's a pending
51:     // read or rewind operation.
52:     virtual void OnUploadDataStreamDestroyed() = 0;
53: 
54:    protected:
55:     Delegate() = default;
56:     virtual ~Delegate() = default;
57:   };
